import math
def control(obs):
    h=obs['hitch_deg']
    cam=obs.get('views',{}).get('camera')
    if not cam:
        return (1.5*h,-0.35,-23)
    chains=[]; chain=[]; prev=None
    for b,d in cam.get('walls',[]):
        a=math.radians(b+h)
        p=(-d*math.cos(a),d*math.sin(a))
        if prev is not None and math.hypot(p[0]-prev[0],p[1]-prev[1])>3:
            if len(chain)>2: chains.append(chain)
            chain=[]
        chain.append(p); prev=p
    if len(chain)>2: chains.append(chain)
    def interp(c,s):
        c=sorted(c)
        for p,q in zip(c,c[1:]):
            if p[0]<=s<=q[0] and q[0]-p[0]>0.01:
                return p[1]+(q[1]-p[1])*(s-p[0])/(q[0]-p[0])
        return None
    L=4.0
    vals=[interp(c,L) for c in chains]
    vals=[v for v in vals if v is not None]
    if len(vals)>=2:
        y=(max(vals)+min(vals))/2
        desired=math.degrees(math.atan2(5.2*y,L*L))
        steer=max(-34,min(34,1.65*(h-desired)))
        speed=-0.75 if abs(h)<20 else -0.45
        return (steer,speed,-23)
    return (max(-34,min(34,1.65*h)),-0.35,-23)

