import math
def control(obs):
    h=obs['hitch_deg']
    cam=obs.get('views',{}).get('camera')
    desired=0.0
    if cam:
        a=math.radians(obs['rig']['trailer_heading_deg'])
        left=[]; right=[]
        for b,d in cam.get('walls',[]):
            q=math.radians(b)-a
            s=-d*math.cos(q); y=d*math.sin(q)
            if s>0.5:
                (left if y>0 else right).append((s,y))
        left.sort(); right.sort()
        def interp(p,s):
            for i in range(len(p)-1):
                x,y=p[i]; xx,yy=p[i+1]
                if x<=s<=xx and xx>x:
                    return y+(yy-y)*(s-x)/(xx-x)
            return None
        aims=[]
        for s in (5.,7.,9.):
            l=interp(left,s); r=interp(right,s)
            if l is not None and r is not None:
                aims.append(math.degrees(math.atan2((l+r)*0.5,s)))
        if aims:
            desired=h+sum(aims)/len(aims)
    desired=max(-38,min(38,desired))
    steer=max(-42,min(42,2.0*h-1.65*desired))
    return steer,-0.85,-41

