            s=-d*math.cos(q); y=d*math.sin(q)
            if s>0.5:
                (left if y>0 else right).append((s,y))
        left.sort(); right.sort()
        def interp(p,s):
            for i in range(len(p)-1):
                x,y=p[i]; xx,yy=p[i+1]
                if x<=s<=xx and xx>x:
                    return y+(yy-y)*(s-x)/(xx-x)
            return None
        aims=[]
        for s in (9.,11.,13.):
            l=interp(left,s); r=interp(right,s)
            if l is not None and r is not None:
                aims.append(math.degrees(math.atan2(20.4*(l+r)*0.5,s*s)))
        if aims:
            desired=sum(aims)/len(aims)
    desired=max(-30,min(30,desired))
    steer=max(-42,min(42,2*h-1.65*desired))
    return steer,-0.4,-41
